def esc(x):return str(x).replace('|','\\|').replace('\n',' ')
def table(headers,rows):return '\n'.join(['|'+'|'.join(headers)+'|','|'+'|'.join('---' for h in headers)+'|']+['|'+'|'.join(esc(x) for x in row)+'|' for row in rows])
def link(n):return f'[{n}]({O/n})'
def h(t):return '\n## '+t+'\n'
def dist(d):return ', '.join(f'{k}: {v}' for k,v in d.items())
family_examples={
 'Bil':'Ifs ordinære nyverdiregel mangler i Bil, selv om samme lokale hovedvilkår er brukt for MC/Bobil. Frende har parkeringsbonusvilkår uten kildegrunnlag. Fremtind-kanalregler holdes adskilt fra felles hovedvilkår.',
 'Innbo':'Tryg Ekstra arver en fellesbod/fellesgarasjegrense fra feil nivå. Storebrand Super har en udokumentert flyttegrense per gjenstand. Beløp, uhellsbegrensninger og oppgjør må vurderes hver for seg.',
 'Hus':'Gjensidige råte/insekt-utvidelse erstatter fortsatt relevante mus/rotter-fakta. Fremtind Standard har utsmyknings-/fradragsspørsmål. Tryg er en detaljrik positiv kontroll; gjenværende P2 og kildeversjonsspørsmål er separate.',
 'Reise':'Gjensidige Pluss arver ordinær enkeltgjenstandsgrense. Storebrands dagsturdekning ligger i geografitekst og blir ukjent på den eksplisitte overnattingsraden. Behandlingsperiode, tilkallelse og reisevarighet må holdes semantisk adskilt.',
 'Snøscooter':'Sparse hovedrader mangler blant annet rettshjelpsgrenser, kjøreutstyr og typebestemte oppgjør. Ingen Bil-nyverdi, vanlig leiebil eller maskinskade importeres uten egen anvendelig kilde.',
 'Campingvogn':'If Super har samme resolverte hovedsett som Kasko og utelater lokale Super-ytelser. Trygs uttrykkelige naturskade og flere fukt-/ferie-/forteltvilkår mangler. Kildekonflikt om andre selskapers nivåer er ikke normalisert bort.',
 'Tilhenger':'Brann/tyveri/Kasko, utstyr, egenandel og rettshjelp er ofte for grovt representert. Campingvognfukt/ferie og trekkbilens regler skal ikke overføres automatisk.',
 'MC':'Gjensidige ferie-leieutvidelse er lagt på Delkasko uten støtte i egen pakke. Fremtind MC har dokumentert ordinær nyverdi som mangler. Tryg1år/10000km er en positiv kontroll.',
 'Bobil':'Gjensidige Kasko utelater dokumentert skadedyr. Utvidede nivåer har konkrete fukt-, ferie-, løsøre- og leasingbetingelser som ikke alle er modellert. DNB/fullvilkår/IPID-konflikter er egne spørsmål.',
 'Båt':'Grove Included-rader skjuler ansvarssummer, egenandeler, alder, geografi, løsøre og ulykkesvilkår. Rekonstruerte toppnivåer mister enkelte grunnfakta. Trygs ordinære hovedvilkår er delvis fraværende lokalt.',
 'Hund':'Veterinærperioder, prosentegenandeler, rase-/aldersvilkår, liv og brukstap er ikke fullstendig modellert. Valgfri rehabilitering/livsavhengighet må bevares som tilvalg, ikke kundens valg.',
 'Katt':'Artsbestemte sykdoms-, tann-, medisin-, ventetids- og livsregler må skilles fra Hund. Frende2025IPID versus2026fullvilkår om forsvinning er fortsatt uavklart.'}
lines=['# SOURCE_CATALOG_COMPLETENESS_AUDIT','', '**COMPLETE — revisjonen av det avgrensede lokale kildegrunnlaget er fullført.**', '', '**Katalogens pilotport: REMEDIATION_REQUIRED.** På spørsmålet om en NITO-rådgiver kan stole på hele produktsammenligningen som beslutningsstøtte: **NEI – REMEDIERING KREVES.** Det finnes samtidig mange korrekte detaljer som må beskyttes. Fullført revisjon betyr ikke at kildene er konfliktfrie eller katalogen klar.']
lines+=[h('VERSION'),f"Revisjon `{A['metadata']['run_id']}`, avsluttet {A['metadata']['timestamp']}. Branch `main`; HEAD `{A['metadata']['head']}`. Frosset katalogtidspunkt: `2026-09-29T10:52:14.812Z`; ikke oppdatert vilkårlig til dagens dato.",f"Katalogfingeravtrykk: `{A['metadata']['catalog_fingerprint']}`. Kildefingeravtrykk: `{A['metadata']['source_corpus_fingerprint']}`.",h('SCOPE'),f"{c['products']} eksakte produktidentiteter: {c['eligible_products']} aktive/valgbare og {c['historical_products']} historiske. {c['addons']} registrerte tillegg, {c['component_fact_definitions']} komponentfakta, {c['families']} familier, {c['providers']} provider-ID-er og {c['scopes']} agreement scopes. Provider-ID-er er ikke ti uavhengige forsikringsgivere. Identitet beholdes som provider × type × scope × produkt × versjon; ukjent versjon forblir ukjent.",h('AUDIT METHOD'), '**REASONABLE.** 45 uavhengige kildeinventarer, tidligere kontrollerte kildepunkter og eksakte produktsupplementer ble brukt. Fullvilkår, tabeller, IPID, produktsider, tillegg og generelle bestemmelser ble undersøkt utover eksisterende canonical keys. Deretter ble kilderegler sammenholdt med faktisk verdi, label, structuredValue, inheritance, komponenter og tilgjengelige tillegg. Til slutt ble katalogens egne påstander kontrollert tilbake mot kildene.',f"{c['manual_source_fact_occurrences']} kilderegel-forekomster / {c['unique_source_semantic_facts']} unike kilde-/sted-/semantikkregler. {c['advisor_relevant_source_fact_occurrences']} er rådgiverrelevante forekomster. {c['base_catalog_fact_occurrences']} basepåstander; {c['reverse_claims_reviewed']} base+tillegg-påstander er reverskontrollert. {c['materialized_comparison_fact_occurrences']} materialiserte aktive fakta er en annen nevner, ikke et avvik.", 'En forekomst er en regel på et eksakt produkt/tillegg. En funnsignatur samler provider/type/scope/konsept/dimensjon/klasse på tvers av nivåer. En rotårsakspost grupperer en dokumentert mekanisme. Disse tallene er ikke antall uavhengige bugs, en statistisk fullstendighetsprosent eller en rangering av selskapene.',h('PRODUCT COVERAGE'),f"204/204 lokalt ferdig gjennomgått; 0 delvis; 0 ikke startet. Alle202 aktive er med; de2 historiske Eika-produktene ble også gjennomgått, uten å aktivere dem. Produktberedskap: {dist(c['product_readiness_distribution'])}. De2 REVIEW_REQUIRED er Tryg Hus-nivåer med P2-detaljer og kildeanvendelsesspørsmål; ikke2 uferdige revisjoner.",f"Fremdrift siden denne fortsettelsens checkpoint: +{RZ['progress_since_current_allocation']['products_fully_audited']} ferdige produkter, +{RZ['progress_since_current_allocation']['addons_fully_audited']} ferdige tillegg, +{RZ['progress_since_current_allocation']['manual_source_fact_occurrences']} regel-forekomster, +{RZ['progress_since_current_allocation']['findings']} funnforekomster.",h('ADD-ON COVERAGE'),f"84/84 registrerte tillegg har avsluttet lokal vurdering av tilgjengelighet, nivå, valgfrihet, grenser, vilkår og proveniens. Beredskap: {dist(c['addon_readiness_distribution'])}. 2 SOURCE_INSUFFICIENT gjelder Gjensidige Bobil Utleie/Fortelt. Oppførte kildebehov og usikker nivåtilgjengelighet er ikke konvertert til sikkert standardinnhold. Tryg separat Leiebil er tidsstyrt; fravær i29.09-snapshot er ikke en kildefeil.",h('SOURCE COVERAGE'),f"322 originaler:246PDF og76HTML;291 unike SHA-256,31 duplikatstier,1437 sider i unike PDF-er. Alle er lesbare. 356 runtime-kildereferanser løser lokalt;338 har oppgitt hash i runtime-metadata,18 uten slik tidligere oppgitt hash er hashberegnet uavhengig i revisjonen. Ingen integritetsfeil.", '314 originalstier er lest med eksakt produktvurdering,6 øvrige er byte-identiske kopier av allerede vurdert innhold,1 er gjennomgått selskapskontekst og1 er erstattet Frende Reise2020 som ikke brukes av et aktivt produkt. Den historiske originalen er identifisert, ikke påstått fullstendig detaljrevidert. Identiske byte beviser ikke identiske sluttprodukter.',f"{link('source-package-matrix.csv')} inneholder76 faktiske provider/familie-pakker. Fem eldre Tryg Bil-originaler mangler nedlastings-URL i lokale metadata;26 funn bruker disse. Lokal fil, vilkårsnummer, dato og hash er bevart. Ingen URL er oppfunnet.",h('BLINDSPOT VALIDATION'), '**CONFIRMED.** At katalogen ikke har et faktum er ikke bevis for at kilden mangler det. Revisjonen fant både manglende kildeopplysninger og kunnskap som er plassert under en annen semantisk nøkkel. 29 synlige falske unknowns er bekreftet med lesende katalog-/presentasjonsprober; øvrige mangler er ikke automatisk telt som observerte UI-feil.',h('GLOBAL CATALOG STATUS'),'**REMEDIATION_REQUIRED**, med samtidige avgrensede SOURCE_RESEARCH_REQUIRED-områder. Ingen bred omskriving av comparison-motor/schema er bevist nødvendig.',h('CATALOG PILOT GATE'),'**REMEDIATION_REQUIRED.** Verifiserte P1-forhold må håndteres før en generell tillitspåstand for NITO-pilot. Materiale kildekonflikter må få korrekt usikker tilstand eller autoritativ avklaring. P2/P3 kan prioriteres etter konkret risiko. Den separate sikkerhets-/GDPR-revisjonen er fortsatt gjeldende og urørt.',h('FAMILY RESULTS')]
lines+=[table(['Familie','Produkter lokalt ferdige','Tillegg ferdige','P1 forekomster','P2 forekomster','Produkter med kildeavklaring'],[[f['family'],f"{f['products_fully_audited']}/{f['products']}",f['addons_complete'],f['P1'],f['P2'],f['source_research_products']] for f in A['family_results']]),'Alle12 familiecheckpoint er COMPLETE. Tilleggene telles i sine registrerte familier. Historiske Eika Reise er med i Reise-tallene.']
